import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { transform } from "esbuild";

/** The public endpoint Worker that the updater redeploys with every new versions.xml asset. */
export const ENDPOINT_WORKER_SOURCE_PATH: string = fileURLToPath(
  new URL("../../version-endpoint/src/index.ts", import.meta.url),
);
export const GENERATED_ENDPOINT_WORKER_PATH: string = fileURLToPath(
  new URL("../src/generated/version-endpoint-worker.ts", import.meta.url),
);

/** Compiles the endpoint Worker's TypeScript source to the JavaScript module the updater uploads. */
export async function compileEndpointWorker(): Promise<string> {
  const source: string = await readFile(ENDPOINT_WORKER_SOURCE_PATH, "utf8");
  const result = await transform(source, {
    loader: "ts",
    format: "esm",
    target: "es2022",
    sourcefile: "version-endpoint/src/index.ts",
  });
  return result.code;
}

/** Renders the generated module that embeds the compiled endpoint Worker. */
export async function renderGeneratedEndpointWorkerModule(): Promise<string> {
  const workerSource: string = await compileEndpointWorker();
  return "// Generated by scripts/generate-endpoint-worker.ts from version-endpoint/src/index.ts.\n"
    + "// Do not edit; run `npm run generate-endpoint-worker` instead.\n"
    + `export const VERSION_ENDPOINT_WORKER_SOURCE: string = ${JSON.stringify(workerSource)};\n`;
}

if (process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1]) {
  await writeFile(GENERATED_ENDPOINT_WORKER_PATH, await renderGeneratedEndpointWorkerModule(), "utf8");
  console.log(`Generated ${GENERATED_ENDPOINT_WORKER_PATH}`);
}
